async function openEditor(id,assetOverride=null,syncUrl=true){if(syncUrl){let target=`/assets/${encodeURIComponent(id)}`;if(window.location.pathname!==target)window.history.pushState({},'',target)}state.asset=assetOverride||state.library?.assets.find(a=>a.id===id);if(!state.asset)return;let defaultVariant=(state.asset.recipes||[]).find(v=>v.id===state.asset.current_variant_id);state.currentVariantId=defaultVariant?.id||null;state.recipe=defaultVariant?variantRecipe(defaultVariant):blankRecipe();state.zoom=1;state.panX=0;state.panY=0;state.img=new Image();state.img.onload=()=>{$('#editorTitle').textContent=`${state.asset.name} · ${state.img.naturalWidth}×${state.img.naturalHeight} · ${formatFileSize(state.asset.size)}`;syncControls();draw()};state.img.src=state.asset.url;$('#editorTitle').textContent=`${state.asset.name} · ${formatFileSize(state.asset.size)}`;$('#editor').classList.remove('hidden');renderVariants();placeVariantExtras();renderAssetTags();loadTags();$('#overwriteVariant').disabled=!state.currentVariantId;}
